      for (var x = 40; x < 1600; x += 200) s += '<rect x="' + x + '" y="600" width="160" height="150" fill="none" stroke="#4a2e1a" stroke-width="4"/>';
      /* büyük kemerli pencere: alacakaranlık ve Venüs */
      s += '<defs><linearGradient id="dfP" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#1a2244"/><stop offset=".6" stop-color="#5a4a6a"/><stop offset="1" stop-color="#d88a58"/></linearGradient></defs>';
      s += '<path d="M1100 560V260A150 150 0 0 1 1400 260V560Z" fill="url(#dfP)" stroke="#3a2414" stroke-width="16"/>';
      s += '<path d="M1100 470Q1180 440 1250 470T1400 460V560H1100Z" fill="#241a24" opacity=".9"/><path d="M1180 470V420h14v-20h10v20h14v50Z" fill="#1a1420"/><path d="M1300 465V400l10-20 10 20v65Z" fill="#1a1420"/>';
      s += '<circle cx="1250" cy="262" r="26" fill="#fff4d8" opacity=".14" class="hale"/><circle class="yp" cx="1250" cy="262" r="5" fill="#fffbe8"/>';
      s += '<path d="M1250 110V560M1100 360H1400" stroke="#3a2414" stroke-width="7"/>';
      /* avize */
      s += '<g class="asili" style="--s:6s;--a:1.5deg"><path d="M760 0V90" stroke="#a8804a" stroke-width="2"/><path d="M700 110Q760 150 820 110" stroke="#c8a060" stroke-width="4" fill="none"/>' +
        [700, 740, 780, 820].map(function (x) { return '<circle cx="' + x + '" cy="104" r="16" fill="#ffe0a0" opacity=".2"/><circle cx="' + x + '" cy="104" r="5" fill="#fff0c8"/>'; }).join("") + "</g>";
      /* duvarda portre: ARISTOTELES */
      s += '<g transform="translate(900 300)"><rect x="-60" y="-80" width="120" height="150" fill="#6a4a24"/><rect x="-50" y="-70" width="100" height="130" fill="#2a2016"/><circle cy="-22" r="24" fill="#c8a080"/><path d="M-24 -10C-24 20 24 20 24 -10C18 10 -18 10 -24 -10Z" fill="#e8e0d0"/><path d="M-40 60C-40 20 40 20 40 60Z" fill="#5a3a4a"/><rect x="-44" y="72" width="88" height="16" fill="#c8a060"/><text y="84" text-anchor="middle" font-family="Georgia,serif" font-size="9" fill="#3a2414" letter-spacing="1">ARISTOTELES</text></g>';
      s += K.raf(40, 420, 210, 330, 44, 4);
      /* masalar */
      var masa = function (x, y, rx) { return '<path d="M' + (x - 8) + " " + y + "V" + (y + 150) + "M" + (x - 40) + " " + (y + 150) + "H" + (x + 40) + '" stroke="#1a120c" stroke-width="12"/><ellipse cx="' + x + '" cy="' + y + '" rx="' + rx + '" ry="' + rx * 0.22 + '" fill="#d8d0c0"/><ellipse cx="' + x + '" cy="' + (y + 4) + '" rx="' + rx + '" ry="' + rx * 0.22 + '" fill="none" stroke="#8a8070" stroke-width="3"/>'; };
      s += masa(760, 700, 150) + masa(1100, 720, 170);
      /* satranç tahtası */
      var t = '<g transform="translate(720 690) scale(1 .38) rotate(45)">';
